import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class ReadingTools {
    public static List<Integer> stableUnique(int[] readings) {
        List<Integer> result = new ArrayList<>();
        if (readings == null) {
            return result;
        }
        Set<Integer> seen = new HashSet<>();
        for (int reading : readings) {
            if (seen.add(reading)) {
                result.add(reading);
            }
        }
        return result;
    }

    public static int[] rotateLeft(int[] values, int shift) {
        if (values == null || values.length == 0) {
            return new int[0];
        }
        int length = values.length;
        int normalized = ((shift % length) + length) % length;
        int[] result = new int[length];
        for (int i = 0; i < length; i++) {
            result[i] = values[(i + normalized) % length];
        }
        return result;
    }
}

stableUnique uses a set for O(n) expected membership checks and a list for encounter order. rotateLeft uses O(n) time and O(n) space; the modulo expression handles both large positive and negative shifts without changing the input.

