import java.io.*;
import java.util.*;

public class Main {
    static class Node { int value; Node left, right; Node(int value) { this.value = value; } }
    static Node insert(Node root, int value) {
        if (root == null) return new Node(value);
        Node current = root;
        while (true) {
            if (value == current.value) return root;
            if (value < current.value) {
                if (current.left == null) { current.left = new Node(value); return root; }
                current = current.left;
            } else {
                if (current.right == null) { current.right = new Node(value); return root; }
                current = current.right;
            }
        }
    }
    static boolean contains(Node root, int value) {
        while (root != null) {
            if (root.value == value) return true;
            root = value < root.value ? root.left : root.right;
        }
        return false;
    }
    static int height(Node root) {
        if (root == null) return 0;
        int levels = 0;
        ArrayDeque<Node> queue = new ArrayDeque<>();
        queue.add(root);
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                Node node = queue.remove();
                if (node.left != null) queue.add(node.left);
                if (node.right != null) queue.add(node.right);
            }
            levels++;
        }
        return levels - 1;
    }
    static void inorder(Node node, StringBuilder out) {
        if (node == null) return;
        inorder(node.left, out);
        if (out.length() > 0) out.append(' ');
        out.append(node.value);
        inorder(node.right, out);
    }
    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(in.readLine().trim());
        Node root = null;
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < n; i++) {
            StringTokenizer parts = new StringTokenizer(in.readLine());
            String command = parts.nextToken();
            if (command.equals("INSERT")) root = insert(root, Integer.parseInt(parts.nextToken()));
            else if (command.equals("CONTAINS")) output.append(contains(root, Integer.parseInt(parts.nextToken())) ? "YES\n" : "NO\n");
            else if (command.equals("HEIGHT")) output.append(height(root)).append('\n');
            else { StringBuilder line = new StringBuilder(); inorder(root, line); output.append(line).append('\n'); }
        }
        System.out.print(output);
    }
}

