import java.io.*;
import java.util.*;

public class Main {
    record Item(int score, String name, int order) {}
    static int compare(Item a, Item b) {
        int byScore = Integer.compare(a.score(), b.score());
        return byScore != 0 ? byScore : a.name().compareTo(b.name());
    }
    static void sort(Item[] a, Item[] temp, int lo, int hi) {
        if (hi - lo <= 1) return;
        int mid = (lo + hi) >>> 1;
        sort(a, temp, lo, mid);
        sort(a, temp, mid, hi);
        int i = lo, j = mid, k = lo;
        while (i < mid && j < hi) {
            if (compare(a[i], a[j]) <= 0) temp[k++] = a[i++];
            else temp[k++] = a[j++];
        }
        while (i < mid) temp[k++] = a[i++];
        while (j < hi) temp[k++] = a[j++];
        System.arraycopy(temp, lo, a, lo, hi - lo);
    }
    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(in.readLine().trim());
        Item[] values = new Item[n];
        for (int i = 0; i < n; i++) {
            StringTokenizer p = new StringTokenizer(in.readLine());
            values[i] = new Item(Integer.parseInt(p.nextToken()), p.nextToken(), i);
        }
        sort(values, new Item[n], 0, n);
        StringBuilder out = new StringBuilder();
        for (Item item : values) out.append(item.score()).append(' ').append(item.name()).append('\n');
        System.out.print(out);
    }
}

