import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner in = new FastScanner(System.in);
        int n = in.nextInt();
        int m = in.nextInt();
        int source = in.nextInt();
        int target = in.nextInt();
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            int u = in.nextInt(), v = in.nextInt();
            graph[u].add(v);
            graph[v].add(u);
        }
        int[] distance = new int[n];
        Arrays.fill(distance, -1);
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        distance[source] = 0;
        queue.add(source);
        while (!queue.isEmpty()) {
            int u = queue.remove();
            if (u == target) break;
            for (int v : graph[u]) {
                if (distance[v] == -1) {
                    distance[v] = distance[u] + 1;
                    queue.add(v);
                }
            }
        }
        System.out.println(distance[target]);
    }
    static class FastScanner {
        private final InputStream input; private final byte[] buffer = new byte[1 << 16]; private int length, position;
        FastScanner(InputStream input) { this.input = input; }
        int read() throws IOException { if (position >= length) { length = input.read(buffer); position = 0; if (length < 0) return -1; } return buffer[position++]; }
        int nextInt() throws IOException { int c; do { c = read(); } while (c <= 32); int sign = 1; if (c == '-') { sign = -1; c = read(); } int value = 0; while (c > 32) { value = value * 10 + c - '0'; c = read(); } return sign * value; }
    }
}

